import React from 'react';

function About({ lang }) {
  return (
    <div>
      <h1>
        {lang === 'ru'
          ? 'Южный федеральный университет'
          : 'Southern Federal University'}
      </h1>
      <p>
        {lang === 'ru'
          ? 'Информация о достижениях автора.'
          : 'Information about the author achievements.'}
      </p>
    </div>
  );
}

export default About;
